def single_path(g, sr, sc, col):
    # minimal non-overlapping L path from (sr,sc) to a cell adjacent to another color's line/cell
    h,w=len(g),len(g[0])
    others={(r,c) for r in range(h) for c in range(w) if g[r][c] and g[r][c]!=col}
    def adj(r,c):
        return any((r+dr,c+dc) in others for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))
    best=None
    for corner in [(sr,sc2) for sc2 in range(w)]+[(sr2,sc) for sr2 in range(h)]:
        (cr,cc)=corner
        # two segments: (sr,sc)->corner->endpoint where endpoint is extension of other segment
        for end in [(cr, sc if cc!=sc else None)]:
            pass
    # enumerate L paths: pick corner (sr, c2) then vertical to r2 ; or corner (r2, sc) then horizontal to c2
    cands=[]
    for c2 in range(w):
        for r2 in range(h):
            seg1=[(sr,c) for c in range(min(sc,c2),max(sc,c2)+1)]
            seg2=[(r,cc) for r in range(min(sr,r2),max(sr,r2)+1)] if c2==cc else [(r,c2) for r in range(min(sr,r2),max(sr,r2)+1)]
            pass
    # simpler: corner at (sr,c2), then vertical to (r2,c2); or corner (r2,sc), then horizontal to (r2,c2)
    for c2 in range(w):
        for r2 in range(h):
            for style in (0,1):
                if style==0:
                    seg1=[(sr,c) for c in range(min(sc,c2),max(sc,c2)+1)]
                    seg2=[(r,c2) for r in range(min(sr,r2),max(sr,r2)+1)]
                else:
                    seg1=[(r,sc) for r in range(min(sr,r2),max(sr,r2)+1)]
                    seg2=[(r2,c) for c in range(min(sc,c2),max(sc,c2)+1)]
                path=set(seg1)|set(seg2)
                if any(g[r][c] not in (0,col) for r,c in path): continue
                ends=[p for p in path if adj(*p) and p!=(sr,sc)]
                if ends:
                    L=len(path)
                    if best is None or L<best[0]: best=(L,path)
    return best[1] if best else set()

